use zopro_bn254::{ifma8::Ifma8,FpConfig,FqConfig,FrConfig};
use std::fs;
const R:&str="/home/ubuntu/src/zopro-perf-work/fused-scale-closure176";
const MASK:u64=(1<<52)-1;
fn words(b:&[u8])->[u64;4]{std::array::from_fn(|j|u64::from_le_bytes(b[j*8..j*8+8].try_into().unwrap()))}
fn digits(w:[u64;4])->[u64;5]{[w[0]&MASK,((w[0]>>52)|(w[1]<<12))&MASK,((w[1]>>40)|(w[2]<<24))&MASK,((w[2]>>28)|(w[3]<<36))&MASK,w[3]>>16]}
fn prime_twice<C:FpConfig>()->[u64;4]{let mut carry=0u128;std::array::from_fn(|j|{let v=(C::P[j]as u128)*2+carry;carry=v>>64;v as u64})}
fn below(a:[u64;4],b:[u64;4])->bool{a.iter().rev().cmp(b.iter().rev()).is_lt()}
fn check<C:FpConfig>(field:u8)->(usize,usize){let bytes=fs::read(format!("{R}/oracle-vectors.bin")).unwrap();assert_eq!(&bytes[..8],b"FSCALE01");assert_eq!((bytes.len()-8)%232,0);let mut logical=0;let mut actual=0;for negative in[false,true]{let records=bytes[8..].chunks_exact(232).filter(|v|v[0]==field&&v[1]==u8::from(negative)).collect::<Vec<_>>();for chunk in records.chunks(8){let inputs:[Ifma8<C,true>;5]=std::array::from_fn(|j|{let lanes=std::array::from_fn(|i|{let record=chunk[i.min(chunk.len()-1)];let w=words(&record[8+32*j..8+32*j+32]);let two=prime_twice::<C>();assert!(w==two||below(w,two));digits(w)});Ifma8::diagnostic_fused_scale_from_digits(lanes)});let[a,b,c,d,f]=inputs;let out=if negative{a.fused_difference_scaled(&b,&c,&d,&f)}else{a.fused_sum_scaled(&b,&c,&d,&f)};let old=if negative{a.difference2(&b,&c,&d).mul(&f)}else{a.sum2(&b,&c,&d).mul(&f)};let raw=out.diagnostic_fused_scale_digits();let canonical=out.get().map(|x|x.to_canonical());let original=old.get().map(|x|x.to_canonical());assert_eq!(canonical,original);for i in 0..8{let record=chunk[i.min(chunk.len()-1)];let raw_expected=words(&record[168..200]);assert!(below(raw_expected,prime_twice::<C>()));assert_eq!(raw[i],digits(raw_expected));assert_eq!(canonical[i],words(&record[200..232]));}logical+=chunk.len();actual+=8;}}(logical,actual)}
#[test]fn native_raw_and_canonical_oracles(){let a=check::<FqConfig>(0);let b=check::<FrConfig>(1);assert_eq!(a.0+b.0,24776);assert_eq!(a.1+b.1,24800);println!("NATIVE_ORACLE logical24776 executed24800 raw24800 canonical24800 original24800 PASS");}
fn chain<C:FpConfig>()->usize{let mut new:[Ifma8<C,true>;5]=std::array::from_fn(|j|Ifma8::new(&std::array::from_fn(|i|zopro_bn254::Fp::<C>::from((j*131+i*37+1)as u64))));let mut old=new;let mut comparisons=0;for step in 0..2048{let negative=step%2==1;let[a,b,c,d,f]=new;let out=if negative{a.fused_difference_scaled(&b,&c,&d,&f)}else{a.fused_sum_scaled(&b,&c,&d,&f)};let[a,b,c,d,f]=old;let reference=if negative{a.difference2(&b,&c,&d).mul(&f)}else{a.sum2(&b,&c,&d).mul(&f)};assert_eq!(out.get(),reference.get());new.rotate_left(1);old.rotate_left(1);new[4]=out;old[4]=reference;comparisons+=8;}comparisons}
#[test]fn native_output_fed_chains(){assert_eq!(chain::<FqConfig>()+chain::<FrConfig>(),32768);println!("NATIVE_CHAIN32768 complete field outputs PASS");}
